"""Learning the race car without a model: MC control, SARSA, Q-learning, Expected SARSA, Double Q.

Episodes start in Cool and end on overheating or after 60 steps (gamma^60 ~ 0.002).
Behaviour is epsilon-greedy (eps = 0.1). True optimal q*: q(C,S)=14.95, q(C,F)=15.5, q(W,S)=14.5, q(W,F)=-10.
"""
import random
GAMMA, EPS, ALPHA = 0.9, 0.1, 0.1
P = {("C", "S"): [(1.0, "C", 1)], ("C", "F"): [(0.5, "C", 2), (0.5, "W", 2)],
     ("W", "S"): [(0.5, "C", 1), (0.5, "W", 1)], ("W", "F"): [(1.0, "O", -10)]}
def step(s, a):
    u, acc = random.random(), 0
    for p, s2, r in P[(s, a)]:
        acc += p
        if u <= acc: return s2, r
def eps_greedy(Q, s):
    return random.choice("SF") if random.random() < EPS else max("SF", key=lambda a: Q[(s, a)])
def fresh(): return {(s, a): 0.0 for s in "CWO" for a in "SF"}

def mc(n):
    Q, N = fresh(), fresh()
    for _ in range(n):
        s, traj = "C", []
        for t in range(60):
            a = eps_greedy(Q, s); s2, r = step(s, a); traj.append((s, a, r)); s = s2
            if s == "O": break
        G, seen = 0.0, {}
        for t in range(len(traj) - 1, -1, -1):
            s, a, r = traj[t]; G = r + GAMMA * G; seen[(s, a)] = G      # overwritten -> first visit wins
        for k, G in seen.items():
            N[k] += 1; Q[k] += (G - Q[k]) / N[k]
    return Q

def td(n, kind):
    Q, Q2 = fresh(), fresh()
    for _ in range(n):
        s = "C"; a = eps_greedy(Q, s)
        for t in range(60):
            s2, r = step(s, a); a2 = eps_greedy(Q, s2)
            if kind == "sarsa": target = r + GAMMA * Q[(s2, a2)]
            elif kind == "q": target = r + GAMMA * max(Q[(s2, b)] for b in "SF")
            elif kind == "esarsa":
                greedy = max("SF", key=lambda b: Q[(s2, b)])
                target = r + GAMMA * sum((1 - EPS + EPS / 2 if b == greedy else EPS / 2) * Q[(s2, b)] for b in "SF")
            if kind == "double":
                A, B = (Q, Q2) if random.random() < 0.5 else (Q2, Q)
                best = max("SF", key=lambda b: A[(s2, b)])
                A[(s, a)] += ALPHA * (r + GAMMA * B[(s2, best)] - A[(s, a)])
            else:
                Q[(s, a)] += ALPHA * (target - Q[(s, a)])
            if s2 == "O": break
            s, a = s2, a2
    if kind == "double":
        return {k: (Q[k] + Q2[k]) / 2 for k in Q}
    return Q

random.seed(3)
print(f"{'method (5,000 episodes)':<26}{'Q(C,S)':>8}{'Q(C,F)':>8}{'Q(W,S)':>8}{'Q(W,F)':>8}   greedy policy")
for name, fn in [("MC first-visit", lambda: mc(5000)), ("SARSA", lambda: td(5000, "sarsa")), ("Expected SARSA", lambda: td(5000, "esarsa")),
                 ("Q-learning", lambda: td(5000, "q")), ("Double Q-learning", lambda: td(5000, "double"))]:
    Q = fn()
    pol = {s: max("SF", key=lambda a: Q[(s, a)]) for s in "CW"}
    print(f"{name:<26}{Q[('C','S')]:8.2f}{Q[('C','F')]:8.2f}{Q[('W','S')]:8.2f}{Q[('W','F')]:8.2f}   Cool->{pol['C']}, Warm->{pol['W']}")
print(f"{'optimal q* (DP)':<26}{14.95:8.2f}{15.5:8.2f}{14.5:8.2f}{-10:8.2f}   Cool->F, Warm->S")
print("\nOn-policy methods (MC, SARSA, Expected SARSA) estimate values of the epsilon-greedy policy,")
print("so they sit below q*; Q-learning and Double Q estimate q* itself.")

# Exact q-values of the epsilon-greedy policy itself (what on-policy methods estimate), by iterating its Bellman equation.
def q_eps(cool_greedy):
    pi = {"C": {cool_greedy: 1 - EPS + EPS / 2, ("S" if cool_greedy == "F" else "F"): EPS / 2}, "W": {"S": 1 - EPS + EPS / 2, "F": EPS / 2}}
    Q = fresh()
    for _ in range(2000):
        V = {s: sum(pi[s][a] * Q[(s, a)] for a in "SF") for s in "CW"}; V["O"] = 0.0
        Q = {**Q, **{(s, a): sum(p * (r + GAMMA * V[s2]) for p, s2, r in P[(s, a)]) for s in "CW" for a in "SF"}}
    return Q
for cg in "FS":
    Q = q_eps(cg)
    print(f"exact q of eps-greedy policy with Cool-greedy={cg}: Q(C,S)={Q[('C','S')]:.2f} Q(C,F)={Q[('C','F')]:.2f} Q(W,S)={Q[('W','S')]:.2f}")
